#!/bin/bash

# Определение функции завершения
function finish_operation {
    echo "Operation completed with criteria: $1"
}

# Определение функции обработки пустого отбора
function process_empty_selection {
    local criteria="$1"
    if [ -z "$criteria" ]; then
        echo "No criteria provided, skipping operation."
    else
        finish_operation "$criteria"
    fi
}

# Определение функции fallback
function fallback {
    local criteria="default_criteria"
    finish_operation "$criteria"
}

# Основная логика
function main {
    local selection_criteria=""
    process_empty_selection "$selection_criteria"
    if [ $? -ne 0 ]; then
        fallback
    fi
}

# Точка входа
main

