    # Используем heredoc для запуска Python-скрипта внутри Bash
    python <<EOF
import signal

# Выводим все поддерживаемые сигналы
for sig in sorted(signal.__dict__.keys()):
    if sig.startswith('SIG'):
        print(sig, signal.__dict__[sig])
EOF
}

# Определение функции для проверки существования сигнала
check_signal() {
    local signal_number=$1
    # Используем heredoc для запуска Python-скрипта внутри Bash
    python <<EOF
import signal

# Проверяем существование сигнала
try:
    signal.signal($signal_number, signal.SIG_IGN)
    print("Signal $signal_number exists")
except ValueError:
    print("Signal $signal_number does not exist")
EOF
}

# Точка входа
list_signals
check_signal 0

