#!/bin/bash

# Evaluation context
base: Собственный slice включает несвязанные редактор, вычислительную задачу и сервис пользователя, не одноразовый тест.
contrast: Тот же slice, только просмотр.

# Function to simulate a user-manager process
user_manager() {
    echo "User manager process running"
}

# Function to simulate an editor task
editor_task() {
    echo "Editor task running"
}

# Function to simulate a computational task
computational_task() {
    echo "Computational task running"
}

# Function to simulate a user service
user_service() {
    echo "User service running"
}

# Wrapper function to limit recursion
wrapper() {
    local count=$1
    if [ "$count" -le 0 ]; then
        return
    fi
    echo "Wrapper count: $count"
    kernel
    wrapper $((count - 1))
}

# Kernel function to execute the slice
kernel() {
    echo "Executing slice..."
    user_manager
    editor_task
    computational_task
    user_service
}

# Main entry point
main() {
